import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import {
  createDatabaseNamed,
  databaseNameOf,
  dropDatabaseNamed,
  isLoopbackUrl,
  withAdminClient,
} from './admin.ts';
import { createDatabase } from './client.ts';
import { refreshMissingSearch } from './search/refresh.ts';

/**
 * The migrations folder: SQL files generated by drizzle-kit (`pnpm db:generate`) or written by
 * hand for triggers and functions (`pnpm db:generate --custom`), plus `meta/_journal.json`,
 * which lists them in order. Never edit a migration once it has been applied (AGENTS.md).
 */
export const MIGRATIONS_DIR = fileURLToPath(new URL('../migrations', import.meta.url));

/**
 * Applies every migration the database hasn't seen yet, each in order. Drizzle records the
 * applied ones in `drizzle.__drizzle_migrations`, so running this again is a no-op.
 */
export async function migrateDatabase(connectionString: string): Promise<void> {
  // A short-lived pool with one connection. Query errors reject `migrate` itself, so idle
  // connection errors can be ignored here.
  const db = createDatabase(connectionString, {
    maxConnections: 1,
    onIdleClientError: () => undefined,
  });
  try {
    await migrate(db, { migrationsFolder: MIGRATIONS_DIR });
    // Search columns are derived in TypeScript, so rows from before they existed (M7-T6) get
    // theirs here; afterwards every change batch keeps them current.
    await refreshMissingSearch(db);
  } finally {
    await db.$client.end();
  }
}

/**
 * Drops the database named in the URL, creates it again empty, and migrates it. Seeding
 * arrives in M1-T11.
 *
 * Refuses any server that isn't on this machine, so a production URL in the environment can't
 * be wiped by accident.
 */
export async function resetDatabase(connectionString: string): Promise<void> {
  if (!isLoopbackUrl(connectionString)) {
    throw new Error('db:reset only runs against a database on this machine (127.0.0.1).');
  }
  const databaseName = databaseNameOf(connectionString);
  await withAdminClient(connectionString, async (client) => {
    await dropDatabaseNamed(client, databaseName);
    await createDatabaseNamed(client, databaseName);
  });
  await migrateDatabase(connectionString);
}
